CREATE TYPE "ExamStatus" AS ENUM ('DRAFT', 'SCHEDULED', 'ONGOING', 'COMPLETED', 'RESULTS_PUBLISHED', 'ARCHIVED');
CREATE TABLE "exams" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "schoolId" UUID NOT NULL, "academicYearId" UUID NOT NULL, "name" VARCHAR(160) NOT NULL, "examType" VARCHAR(80) NOT NULL, "startDate" DATE NOT NULL, "endDate" DATE NOT NULL, "status" "ExamStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "exams_pkey" PRIMARY KEY ("id"), CONSTRAINT "exams_school_fkey" FOREIGN KEY ("schoolId") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "exams_year_fkey" FOREIGN KEY ("academicYearId") REFERENCES "academic_years"("id") ON DELETE RESTRICT, CONSTRAINT "exams_dates_check" CHECK ("endDate" >= "startDate"));
CREATE TABLE "exam_schedules" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "schoolId" UUID NOT NULL, "examId" UUID NOT NULL, "classId" UUID NOT NULL, "subjectId" UUID NOT NULL, "examDate" DATE NOT NULL, "startTime" TIME(0) NOT NULL, "endTime" TIME(0) NOT NULL, "room" VARCHAR(120), "maxMarks" DECIMAL(8,2) NOT NULL, "passMarks" DECIMAL(8,2) NOT NULL, "instructions" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "exam_schedules_pkey" PRIMARY KEY ("id"), CONSTRAINT "exam_schedules_school_fkey" FOREIGN KEY ("schoolId") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "exam_schedules_exam_fkey" FOREIGN KEY ("examId") REFERENCES "exams"("id") ON DELETE CASCADE, CONSTRAINT "exam_schedules_class_fkey" FOREIGN KEY ("classId") REFERENCES "academic_classes"("id") ON DELETE RESTRICT, CONSTRAINT "exam_schedules_subject_fkey" FOREIGN KEY ("subjectId") REFERENCES "subjects"("id") ON DELETE RESTRICT, CONSTRAINT "exam_schedules_marks_check" CHECK ("maxMarks" > 0 AND "passMarks" >= 0 AND "passMarks" <= "maxMarks"), CONSTRAINT "exam_schedules_time_check" CHECK ("endTime" > "startTime"));
CREATE TABLE "grading_schemes" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "schoolId" UUID NOT NULL, "name" VARCHAR(120) NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "grading_schemes_pkey" PRIMARY KEY ("id"), CONSTRAINT "grading_schemes_school_fkey" FOREIGN KEY ("schoolId") REFERENCES "schools"("id") ON DELETE CASCADE);
CREATE TABLE "grading_scale_items" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "gradingSchemeId" UUID NOT NULL, "minPercentage" DECIMAL(5,2) NOT NULL, "maxPercentage" DECIMAL(5,2) NOT NULL, "grade" VARCHAR(20) NOT NULL, "gradePoint" DECIMAL(5,2), "remark" VARCHAR(240), "sortOrder" INTEGER NOT NULL, CONSTRAINT "grading_scale_items_pkey" PRIMARY KEY ("id"), CONSTRAINT "grading_items_scheme_fkey" FOREIGN KEY ("gradingSchemeId") REFERENCES "grading_schemes"("id") ON DELETE CASCADE, CONSTRAINT "grading_items_range_check" CHECK ("minPercentage" >= 0 AND "maxPercentage" <= 100 AND "minPercentage" <= "maxPercentage"));
CREATE INDEX "exams_school_year_status_idx" ON "exams"("schoolId", "academicYearId", "status");
CREATE INDEX "exams_school_start_idx" ON "exams"("schoolId", "startDate");
CREATE UNIQUE INDEX "exam_schedules_tuple_key" ON "exam_schedules"("examId", "classId", "subjectId");
CREATE INDEX "exam_schedules_lookup_idx" ON "exam_schedules"("schoolId", "examId", "classId", "subjectId");
CREATE UNIQUE INDEX "grading_schemes_one_default_idx" ON "grading_schemes"("schoolId") WHERE "isDefault" = true;
CREATE INDEX "grading_schemes_school_default_idx" ON "grading_schemes"("schoolId", "isDefault");
CREATE INDEX "grading_items_scheme_sort_idx" ON "grading_scale_items"("gradingSchemeId", "sortOrder");
